import { Get } from 'type-fest';
import { Dict } from './dict.js';
import { ChangePathDelimiter } from './objectKeyPaths.js';

type GetTypeByPath<State extends Dict, Path extends string, Delimiter extends string = "."> = Path extends "" | undefined ? State : Get<State, ChangePathDelimiter<Path, ".", Delimiter>>;

export type { GetTypeByPath };
